import java.io.*;
import java.util.*;

public class Solution {
    static class SegmentTree {
            int n;
                    int[] tree;

                            public SegmentTree(int n, char[] s, int[] tin, int[] nodeAtTin) {
                                        this.n = n;
                                                    tree = new int[4 * n];
                                                                build(1, 0, n - 1, s, tin, nodeAtTin);
                                                                        }

                                                                                private void build(int node, int start, int end, char[] s, int[] tin, int[] nodeAtTin) {
                                                                                            if (start == end) {
                                                                                                            int u = nodeAtTin[start];
                                                                                                                            tree[node] = 1 << (s[u] - 'a');
                                                                                                                                            return;
                                                                                                                                                        }
                                                                                                                                                                    int mid = (start + end) / 2;
                                                                                                                                                                                build(2 * node, start, mid, s, tin, nodeAtTin);
                                                                                                                                                                                            build(2 * node + 1, mid + 1, end, s, tin, nodeAtTin);
                                                                                                                                                                                                        tree[node] = tree[2 * node] ^ tree[2 * node + 1];
                                                                                                                                                                                                                }

                                                                                                                                                                                                                        public void update(int node, int start, int end, int idx, int val) {
                                                                                                                                                                                                                                    if (start == end) {
                                                                                                                                                                                                                                                    tree[node] = val;
                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                            int mid = (start + end) / 2;
                                                                                                                                                                                                                                                                                                        if (idx <= mid) {
                                                                                                                                                                                                                                                                                                                        update(2 * node, start, mid, idx, val);
                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                    update(2 * node + 1, mid + 1, end, idx, val);
                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                            tree[node] = tree[2 * node] ^ tree[2 * node + 1];
                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                            public int query(int node, int start, int end, int l, int r) {
                                                                                                                                                                                                                                                                                                                                                                                                        if (r < start || end < l) return 0;
                                                                                                                                                                                                                                                                                                                                                                                                                    if (l <= start && end <= r) return tree[node];
                                                                                                                                                                                                                                                                                                                                                                                                                                int mid = (start + end) / 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                            return query(2 * node, start, mid, l, r) ^ query(2 * node + 1, mid + 1, end, l, r);
                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            public List<Boolean> palindromePath(int n, int[][] edges, String s_str, String[] queries) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    List<List<Integer>> adj = new ArrayList<>();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for (int[] edge : edges) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                adj.get(edge[0]).add(edge[1]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            adj.get(edge[1]).add(edge[0]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int[] parent = new int[n];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int[] depth = new int[n];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int[] heavy = new int[n];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Arrays.fill(heavy, -1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int[] sz = new int[n];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    dfsSize(0, -1, 0, adj, sz, depth, parent, heavy);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int[] head = new int[n];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int[] pos = new int[n];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int[] nodeAtTin = new int[n];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int[] timer = new int[1];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            dfsHld(0, 0, adj, heavy, head, pos, nodeAtTin, timer, parent);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    char[] s = s_str.toCharArray();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            SegmentTree st = new SegmentTree(n, s, pos, nodeAtTin);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    List<Boolean> result = new ArrayList<>();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (String q : queries) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        String[] parts = q.split(" ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (parts[0].equals("update")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int u = Integer.parseInt(parts[1]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    char c = parts[2].charAt(0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    s[u] = c;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    st.update(1, 0, n - 1, pos[u], 1 << (c - 'a'));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int u = Integer.parseInt(parts[1]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int v = Integer.parseInt(parts[2]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int pathMask = queryPath(u, v, head, pos, depth, parent, st);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // A bitmask forms a palindrome if it has at most one bit set
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                boolean isPalindrome = (pathMask == 0) || ((pathMask & (pathMask - 1)) == 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                result.add(isPalindrome);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return result;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    private int dfsSize(int u, int p, int d, List<List<Integer>> adj, int[] sz, int[] depth, int[] parent, int[] heavy) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            parent[u] = p;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    depth[u] = d;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            sz[u] = 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int maxSub = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (int v : adj.get(u)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (v != p) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int subSz = dfsSize(v, u, d + 1, adj, sz, depth, parent, heavy);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sz[u] += subSz;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (subSz > maxSub) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            maxSub = subSz;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                heavy[u] = v;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return sz[u];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    private void dfsHld(int u, int h, List<List<Integer>> adj, int[] heavy, int[] head, int[] pos, int[] nodeAtTin, int[] timer, int[] parent) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            head[u] = h;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pos[u] = timer[0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            nodeAtTin[timer[0]++] = u;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (heavy[u] != -1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                dfsHld(heavy[u], h, adj, heavy, head, pos, nodeAtTin, timer, parent);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (int v : adj.get(u)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (v != parent[u] && v != heavy[u]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            dfsHld(v, v, adj, heavy, head, pos, nodeAtTin, timer, parent);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        private int queryPath(int u, int v, int[] head, int[] pos, int[] depth, int[] parent, SegmentTree st) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int resMask = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        while (head[u] != head[v]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (depth[head[u]] < depth[head[v]]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int temp = u; u = v; v = temp;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int l = pos[head[u]], r = pos[u];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        resMask ^= st.query(1, 0, st.n - 1, l, r);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    u = parent[head[u]];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (depth[u] > depth[v]) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int temp = u; u = v; v = temp;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                int l = pos[u], r = pos[v];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        resMask ^= st.query(1, 0, st.n - 1, l, r);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return resMask;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }